    @Override public InteractionResult place(BlockPlaceContext context){if(((NativeGearBlock)getBlock()).definition().kind==NativeGearDefinition.Kind.TRACK){var supporting=NativeGearFormation.at(context.getLevel(),context.getClickedPos().relative(context.getClickedFace().getOpposite()));var controller=supporting==null?null:supporting.controllerEntity();if(controller!=null&&controller.progress()!=1)return InteractionResult.FAIL;}var support=NativeGearFormation.at(context.getLevel(),context.getClickedPos().relative(context.getClickedFace().getOpposite()));var root=support==null?null:support.controllerEntity();if(root!=null&&root.assembly()!=null&&root.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.NONE&&root.definition().kind==NativeGearDefinition.Kind.ROTATING&&root.progress()!=1&&((NativeGearBlock)getBlock()).definition().foot()){if(context.getLevel().isClientSide)return InteractionResult.SUCCESS;return context.getPlayer() instanceof ServerPlayer actor&&NativeGearMechanismUsePayload.apply(actor,new NativeGearMechanismUsePayload(root.getBlockPos(),root.identity(),2))?InteractionResult.CONSUME:InteractionResult.FAIL;}var frame=((NativeGearBlock)getBlock()).definition().foot()&&support!=null?support.mount():Direction.DOWN;return NativeGearComponents.placing(frame,()->placeComponent(context,null));}
